struct	PACKET_ZC_ITEM_FALL_ENTRY2
{
	CLIENT_ZONE_PACKET_TYPE;
	short	PacketLength;
	DWORD	ITAID;
	WORD	ITID;
	bool	IsIdentified;
	short	xPos;
	short	yPos;
	BYTE	subX;
	BYTE	subY;
	short	count;

	inline void Init(
		const DWORD	in_ITAID,
		const WORD	in_ITID,
		const BYTE	in_IsIdentified,
		const short	in_xPos,
		const short	in_yPos,
		const BYTE	in_subX,
		const BYTE	in_subY,
		const short	in_count){
			ITAID = in_ITAID;
			ITID = in_ITID;
			IsIdentified = in_IsIdentified;
			xPos = in_xPos;
			yPos = in_yPos;
			subX = in_subX;
			subY = in_subY;
			count = in_count;
	};
	inline void Crypt(void){
		*(((unsigned char*)&ITAID) +1 ) ^= (unsigned char)yPos;
		*(((unsigned char*)&ITAID) +3 ) ^= (unsigned char)ITID;
	};
};


