inline	void	EncodePosDir(int srcx, int srcy, int srcdir, BYTE *result)
{
	result[0] = (srcx&0x3FC) >> 2;
	result[1] = ((srcx&0x3) << 6) | ((srcy&0x3F0) >> 4);
	result[2] = ((srcy&0xF) << 4) | (srcdir&0xF);
}

inline	void	DecodePosDir(BYTE *packet, int &resultx, int &resulty, int &resultdir)
{
	resultx = packet[0] & 0xff;
	resultx = (resultx<<2) | ((packet[1]&0xC0) >> 6);
	resulty = (packet[1] & 0x3f);
	resulty = (resulty<<4) | ((packet[2]&0xFF) >> 4);
	resultdir = (packet[2] & 0xf);
}

inline	void	EncodeSrcDst(int srcx, int srcy, int dstx, int dsty, int xcellpos, int ycellpos, BYTE *result)
{
	result[0] = (srcx&0x3FF) >> 2;
	result[1] = ((srcx&0x3) << 6) | ((srcy&0x3F0) >> 4);
	result[2] = ((srcy&0xF) << 4) | ((dstx&0x3C0) >> 6);
	result[3] = ((dstx&0x3F) << 2) | ((dsty&0x300) >> 8);
	result[4] = (dsty&0xFF);
	result[5] = ((xcellpos&0xF) << 4) | (ycellpos&0xF);
}

inline	void	DecodeSrcDst(BYTE *packet, int &rsx, int &rsy, int &rdx, int &rdy, int &xcellpos, int &ycellpos)
{
	rsx = packet[0] & 0xff;
	rsx = (rsx<<2) | ((packet[1]&0xC0) >> 6);
	rsy = (packet[1] & 0x3f);
	rsy = (rsy<<4) | ((packet[2]&0xF0) >> 4);
	rdx = (packet[2] & 0xF);
	rdx = (rdx<<6) | ((packet[3]&0xFC) >> 2);
	rdy = (packet[3] & 0x3);
	rdy = (rdy<<8) | (packet[4]&0xff);
	xcellpos = (packet[5]&0xF0) >> 4;
	ycellpos = (packet[5]&0xF);
}

